import {CATEGORIES,LIMITS,fresh,inRange,summarize,confirmReview,postPending,ioUs} from './model.js';

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n/100);
const dateText=s=>new Date(s+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});
const KEY='saveup-inbox-lab-v1';
const paths={
  list:'M7 6h14M7 12h14M7 18h14M3 6h.01M3 12h.01M3 18h.01',
  cards:'M7 7h13v14H7zM3 17V3h13',
  layers:'m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5',
  inbox:'M4 4h16l2 12v4H2v-4L4 4ZM2 15h6l2 3h4l2-3h6',
  chart:'M4 20V10M12 20V4M20 20v-7',
  heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',
  people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-3.9M16 3.1a4 4 0 0 1 0 7.8M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',
  bag:'M5 7h14l1 14H4L5 7ZM8 8V6a4 4 0 0 1 8 0v2',
  basket:'M3 10h18l-2 10H5L3 10ZM7 10l4-7M17 10l-4-7M9 14v3M15 14v3',
  arrows:'M4 7h15l-4-4M20 17H5l4 4M19 7l-4 4M5 17l4-4',
  receipt:'M5 3h14v19l-3-2-4 2-4-2-3 2V3ZM9 7h6M9 11h6M9 15h3',
  coat:'m8 3-5 4-2 9 4 1 2-7v11h10V10l2 7 4-1-2-9-5-4-4 4-4-4ZM12 7v14',
  cup:'M4 7h13v8a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5V7ZM17 8h2a3 3 0 0 1 0 6h-2M7 3v1M12 2v2',
  train:'M6 3h12a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2ZM4 11h16M8 15h.01M16 15h.01M8 19l-3 3M16 19l3 3M12 3v8',
  camera:'M3 6h4l2-3h6l2 3h4v15H3V6ZM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',
  plus:'M12 5v14M5 12h14',chevron:'m8 4 8 8-8 8',down:'m6 9 6 6 6-6',left:'m15 5-7 7 7 7',
  close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',info:'M12 16v-4M12 8h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',
  reset:'M3 10a9 9 0 1 1 2 9M3 3v7h7',share:'M12 15V2m-4 4 4-4 4 4M5 10H3v12h18V10h-2',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',
  edit:'m14 4 6 6M4 20l5-1L21 7l-6-6L3 13l1 7Z',wallet:'M3 5h17v16H3V5Zm0 0 13-3v3M15 11h7v6h-7v-6Z'
};
const icon=name=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.bag}"/></svg>`;
const clay=(name,tone='blue')=>`<span class="clay-icon ${tone}" aria-hidden="true">${icon(name)}</span>`;
const tray=()=>'<div class="clay-inbox" aria-hidden="true"><span class="paper"></span><span class="tray"></span><span class="check">✓</span></div>';
let storageAvailable=true, saved;
try {saved=JSON.parse(localStorage.getItem(KEY)||'null');}catch{storageAvailable=false;}
// Retain the existing Focused review data, including when arriving from an old mode link.
const states=saved?.version===1 && saved.states?saved.states:{};
if(!states.focused?.transactions)states.focused=fresh();
const concept='focused';
const inboxUrl=new URL(location.href);
if(inboxUrl.searchParams.has('concept')){inboxUrl.searchParams.delete('concept');history.replaceState(null,'',inboxUrl);}
let page='inbox',filter='needs',activeId=null,draft=null,toastTimer,focusBeforeDialog;
let expandedId=null,reviewInline=false;
const inlineDrafts={focused:{}};
const inlineCategories={focused:{}};
const state=()=>states[concept];
function persist(){try{localStorage.setItem(KEY,JSON.stringify({version:1,concept,states}));}catch{storageAvailable=false;}}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3400);}
function progressCard(){
  const s=summarize(state()),done=s.total>0&&s.total===s.reviewed,percent=s.total?Math.round(s.reviewed/s.total*100):0;
  const pending=inRange(state()).filter(t=>t.status==='pending').length;
  return `<section class="progress-card reconciliation-card" aria-label="Weekly reconciliation"><div class="progress-top"><div><h2>${done?'Week reconciled':'Weekly reconciliation'}</h2><p>${s.total?`${s.reviewed} of ${s.total} reviewed · ${s.total-s.reviewed} left`:'No transactions in this date range'}</p></div><div class="progress-number">${percent}<span>%</span></div></div><div class="track" role="progressbar" aria-label="Transactions reconciled" aria-valuemin="0" aria-valuemax="${s.total||1}" aria-valuenow="${s.reviewed}" aria-valuetext="${s.reviewed} of ${s.total} transactions reviewed"><span style="width:${percent}%"></span></div><div class="progress-foot"><span class="${s.unclassified?'':'positive'}">${s.unclassified?`${s.unclassified} transfers to classify`:done?'✓ Every transaction reviewed':'Every decision counts'}</span><span>${pending?`${pending} pending at bank`:s.total?'All bank activity posted':''}</span></div></section>`;
}
function badge(t){return t.reviewed?`<span class="badge reviewed">✓ Reviewed${t.status==='pending'?' · Pending':''}</span>`:t.kind==='transfer'?'<span class="badge transfer">Classify</span>':`<span class="badge ${t.status}">${t.status==='cash'?'Manual cash':t.status==='pending'?'● Pending':'Posted'}</span>`;}
function visible(){return inRange(state()).filter(t=>filter==='all'||(filter==='reviewed'?t.reviewed:!t.reviewed));}
function filterBar(){const tx=inRange(state());return `<div class="filters" aria-label="Review filter">${[['needs','Needs review',tx.filter(t=>!t.reviewed).length],['all','All',tx.length],['reviewed','Reviewed',tx.filter(t=>t.reviewed).length]].map(([key,label,n])=>`<button class="${filter===key?'active':''}" data-action="filter" data-key="${key}" aria-pressed="${filter===key}">${label}<span class="count">${n}</span></button>`).join('')}</div>`;}
function emptyInbox(){const complete=filter==='needs'&&inRange(state()).length>0;return `<div class="empty">${clay('check','green')}<h2>${complete?'You’re all caught up.':'Nothing here just yet.'}</h2><p>${complete?'Every transaction has a place. See how your week fits your budget.':'Try a different filter or date range.'}</p><button class="secondary" data-action="${complete?'page':'dates'}" ${complete?'data-key="week"':''}>${complete?'See my week':'Change date range'} ${icon('chevron')}</button></div>`;}
function focusedRow(t){
  const open=expandedId===t.id, savedDraft=inlineDrafts[concept][t.id];
  const split=savedDraft?.split??t.split??!!t.receipt;
  const category=inlineCategories[concept][t.id]??savedDraft?.category??t.category??t.suggestion??'';
  const hint=t.changed?'Amount changed · review again':t.reviewed?(split?'Split across budgets & IOUs':t.classification==='own'?'Between your accounts':t.classification==='income'?'Confirmed income':t.description||t.category):t.hint;
  const detailLabel=t.kind==='transfer'?'Purpose & details':split?'Receipt, splits & IOUs':t.planId?'Planned match, splits & IOUs':'Details, splits & IOUs';
  return `<article class="focused-transaction ${open?'expanded':''}" data-transaction="${t.id}">
    <button class="transaction focused-summary" data-action="inline-details" data-id="${t.id}" aria-expanded="${open}" aria-controls="details-${t.id}" aria-label="${open?'Collapse':'Expand'} ${esc(t.name)} details">${clay(t.icon,t.tone)}<span class="transaction-copy"><span class="transaction-name">${esc(t.name)}</span><span class="transaction-hint">${esc(hint||'Choose a category')}</span></span><span class="transaction-side"><span class="amount">${t.direction==='in'?'+':''}${money(t.amount)}</span>${badge(t)}</span></button>
    ${open?'':t.kind==='transfer'?`<div class="inline-transfer"><span>${t.reviewed?'Purpose confirmed':'Excluded from totals until classified'}</span><button class="inline-expand" data-action="inline-details" data-id="${t.id}" aria-expanded="false" aria-controls="details-${t.id}">${t.reviewed?'Edit purpose':'Classify transfer'} ${icon('down')}</button></div>`:split?`<button class="inline-expand allocation-summary" data-action="inline-details" data-id="${t.id}" aria-expanded="false" aria-controls="details-${t.id}">${icon('receipt')} ${t.lines?.length||savedDraft?.lines?.length||1} items · ${t.reviewed?'Edit split & IOUs':'Choose categories & IOUs'} ${icon('down')}</button>`:`<div class="inline-category-row"><label class="inline-category-label"><span>${t.reviewed?'Budget category':'Suggested category'}</span><select class="inline-category" data-id="${t.id}" aria-label="Budget category for ${esc(t.name)}">${options(category,true)}</select></label><button class="inline-confirm" data-action="${t.planId?'inline-details':'inline-confirm'}" data-id="${t.id}">${t.planId?'Match & review':t.reviewed?'Save':`${icon('check')} Review`}</button></div>`}
    <button class="inline-expand details-toggle" data-action="inline-details" data-id="${t.id}" aria-expanded="${open}" aria-controls="details-${t.id}">${open?'Close details':detailLabel} ${icon(open?'down':'plus')}</button>
    <div id="details-${t.id}" class="inline-details" ${open?'':'hidden'} role="region" aria-label="${esc(t.name)} transaction details"></div>
    <p class="form-error inline-error" role="alert" hidden></p>
  </article>`;
}
function focusedView(){const tx=visible();if(!tx.length)return emptyInbox();const dates=[...new Set(tx.map(t=>t.date))].sort().reverse();return dates.map(d=>`<div class="section-label"><span>${d==='2026-10-31'?'Saturday':dateText(d)}</span><span>${tx.filter(t=>t.date===d).length} ${tx.filter(t=>t.date===d).length===1?'transaction':'transactions'}</span></div><div class="transaction-list">${tx.filter(t=>t.date===d).map(focusedRow).join('')}</div>`).join('');}
function inbox(){return `<div class="page-heading"><div><h1>Focused Inbox</h1><button class="week-button" data-action="dates">${dateText(state().range.start)} – ${dateText(state().range.end)} ${icon('down')}</button></div>${tray()}</div>${progressCard()}${filterBar()}${focusedView()}<div class="action-row"><button data-action="scan">${icon('camera')} Scan receipt</button><button data-action="manual">${icon('plus')} Add manually</button></div><p class="fine-print">Sample week: October 25–31, 2026<br>Your changes stay in this browser.</p>${!storageAvailable?'<p class="storage-warning">Browser storage is unavailable. Changes last only for this visit.</p>':''}`;}
function week(){const s=summarize(state());return `<div class="view-toolbar"><button class="text-button" data-action="dates">Change dates</button></div><div class="page-heading"><div><h1>A clearer week</h1><p>${dateText(state().range.start)} – ${dateText(state().range.end)}</p></div>${clay('chart')}</div>${progressCard()}<section class="balance-card"><div class="eyebrow">ROOM AFTER PLANS</div><div class="big-amount ${s.remaining<0?'negative':''}">${money(s.remaining)}</div><p class="caption">of a $500 sample weekly budget</p><div class="budget-track" aria-label="${money(s.posted+s.cash)} confirmed spending, ${money(s.pending)} pending, ${money(s.reserved)} reserved for plans"><span class="posted-fill" style="width:${Math.min(100,(s.posted+s.cash)/50000*100)}%"></span><span class="pending-fill" style="width:${s.pending/50000*100}%"></span><span class="plan-fill" style="width:${s.reserved/50000*100}%"></span></div><div class="legend"><span>Confirmed ${money(s.posted+s.cash)}</span><span>Pending ${money(s.pending)}</span><span>Planned ${money(s.reserved)}</span></div></section>${s.reviewed<s.total?`<div class="info-callout"><strong>Still a work in progress.</strong> ${s.total-s.reviewed} unreviewed transactions aren’t in these spending totals yet.${s.unclassified?` This includes ${s.unclassified} transfers (${money(s.unclassifiedAmount)} in combined activity) waiting for a purpose.`:''}</div>`:''}<div class="metric-grid"><div class="metric"><small>Before planned reservations</small><strong>${money(50000-s.spent)}</strong></div><div class="metric"><small>Confirmed income</small><strong>${money(s.income)}</strong></div></div><section class="balance-card"><h2 style="font-size:16px">Your budgets</h2>${CATEGORIES.map(c=>{const b=s.categories[c],total=b.posted+b.pending+b.cash,pc=Math.round(total/LIMITS[c]*100);return `<div class="budget-row"><div class="budget-title"><span>${c}</span><span class="${pc>100?'negative':''}">${pc}%</span></div><div class="track"><span style="width:${Math.min(pc,100)}%"></span></div><p>${money(total)} / ${money(LIMITS[c])}${b.pending?` · ${money(b.pending)} pending`:''}</p></div>`;}).join('')}</section><p class="fine-print">Reviewed pending charges count provisionally. IOU portions are tracked separately; the original card charge stays intact. Planned reservations use the midpoint estimate in this prototype.</p>`;}
function plans(){return `<div class="page-heading"><div><h1>Ahead of you</h1><p>A little intention before you spend.</p></div>${clay('heart','pink')}</div>${state().plans.map(p=>`<article class="plan-card"><div class="plan-top">${clay('coat','peach')}<div><h2>${p.name}</h2><p>${money(p.low)} – ${money(p.high)}</p><span class="badge ${p.matchedTransaction?'reviewed':'pending'}">${p.matchedTransaction?'✓ Matched to purchase':'Essential · planned'}</span></div></div>${p.matchedTransaction?`<div class="info-callout">Matched to UNIQLO · ${money(state().transactions.find(t=>t.id===p.matchedTransaction).amount)}. The ${money(p.reserve)} planned reservation is released, so it isn’t counted twice.</div><button class="secondary" data-action="review" data-id="${p.matchedTransaction}">View matched purchase</button>`:`<div class="section-label"><span>Sample savings</span><span>${money(p.saved)} / ${money(p.reserve)}</span></div><div class="track"><span style="width:${p.saved/p.reserve*100}%"></span></div><p class="fine-print">${money(p.reserve)} reserved in this demo · no money moved</p><button class="primary" data-action="review" data-id="coat">Review possible match ${icon('chevron')}</button>`}</article>`).join('')}<div class="info-callout">A planned purchase is an intention. Only your confirmation connects it to an actual transaction.</div>`;}
function iouPage(){const items=ioUs(state());return `<div class="page-heading"><div><h1>Between friends</h1><p>Small things, remembered.</p></div>${clay('people','lavender')}</div>${items.length?`<section class="balance-card"><div class="eyebrow">OWED TO YOU</div><div class="big-amount">${money(items.reduce((n,l)=>n+l.amount,0))}</div><p class="caption">Kept separate from your own budget spending</p></section>${items.map(l=>`<button class="iou-card" style="width:100%;text-align:left" data-action="review" data-id="${l.id}"><span class="avatar">${esc(l.person[0].toUpperCase())}</span><span><h2>${esc(l.person)}</h2><p>${esc(l.name)} · ${esc(l.transaction)}</p></span><strong>${money(l.amount)}</strong></button>`).join('')}<div class="info-callout">These are sample IOUs, not payment requests. No messages or money are sent.</div>`:`<div class="empty">${clay('people','lavender')}<h2>A chocolate bar for a friend?</h2><p>Open the Target receipt and assign an item to someone. It will show up here as an IOU.</p><button class="primary" data-action="review" data-id="target">Try a receipt split ${icon('chevron')}</button></div>`}`;}
function render(){
  rememberInlineDraft();
  const previousProgress=$('.reconciliation-card .track>span')?.style.width;
  $('.app-shell').dataset.concept=page==='inbox'?concept:'';
  $('#about-button').innerHTML=icon('info');
  $('#main').innerHTML=page==='inbox'?inbox():page==='week'?week():page==='plans'?plans():iouPage();
  if(reviewInline && expandedId && document.getElementById('details-'+expandedId)) renderReview();
  const progress=$('.reconciliation-card .track>span');
  if(progress && previousProgress && !matchMedia('(prefers-reduced-motion: reduce)').matches){const next=progress.style.width;progress.style.width=previousProgress;requestAnimationFrame(()=>requestAnimationFrame(()=>{if(progress.isConnected)progress.style.width=next;}));}
  $('#bottom-nav').innerHTML=[['inbox','inbox','Inbox'],['week','chart','My week'],['plans','heart','Plans'],['ious','people','IOUs']].map(([key,ic,label])=>`<button class="${key===page?'selected':''}" data-action="page" data-key="${key}" ${page===key?'aria-current="page"':''}><span class="nav-icon">${icon(ic)}</span>${label}</button>`).join('');
}
function showSheet(title,body){const d=$('#sheet');if(!d.open)focusBeforeDialog=document.activeElement;d.innerHTML=`<div class="sheet-inner"><div class="sheet-handle"></div><header class="sheet-header"><h2 id="sheet-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog" autofocus>${icon('close')}</button></header>${body}</div>`;if(!d.open)d.showModal();document.body.classList.add('modal-open');}
function closeSheet(){const d=$('#sheet');if(d.open)d.close();document.body.classList.remove('modal-open');if(focusBeforeDialog?.isConnected)focusBeforeDialog.focus({preventScroll:true});}
$('#sheet').addEventListener('close',()=>{document.body.classList.remove('modal-open');});
$('#sheet').addEventListener('click',e=>{if(e.target===$('#sheet')){const r=$('#sheet').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSheet();}});
const options=(value,blank=false)=>(blank?'<option value="">Choose a category</option>':'')+CATEGORIES.map(c=>`<option ${value===c?'selected':''}>${c}</option>`).join('');
function readDraft(){const form=$('#review-form');if(!form)return;const f=new FormData(form);draft.description=f.get('description')??draft.description??'';draft.note=f.get('note')??draft.note??'';draft.priority=Number(f.get('priority')||draft.priority||3);draft.category=f.get('category')??draft.category??'';draft.classification=f.get('classification')||draft.classification||'';draft.matchPlan=f.has('matchPlan');
 if(draft.split){draft.lines=[...form.querySelectorAll('.receipt-line')].map((el,i)=>({name:el.querySelector('[data-line="name"]').value.trim(),amount:Math.round(Number(el.querySelector('[data-line="amount"]').value)*100),category:el.querySelector('[data-line="category"]').value,person:el.querySelector('[data-line="iou"]').checked?el.querySelector('[data-line="person"]').value.trim():'',iouEnabled:el.querySelector('[data-line="iou"]').checked}));}}
function initialDraft(t){return {description:t.description||'',category:inlineCategories[concept][t.id]??t.category??t.suggestion??'',classification:t.classification||'',note:t.note||'',priority:t.priority||3,split:t.split??!!t.receipt,lines:structuredClone(t.lines||[{name:t.description||t.name,amount:t.amount,category:t.category||t.suggestion||'Essentials',person:''}]),matchPlan:!!state().plans.find(p=>p.matchedTransaction===t.id)};}
function rememberInlineDraft(){
  if(reviewInline && activeId && $('#review-form')?.dataset.transaction===activeId){readDraft();inlineDrafts[concept][activeId]=structuredClone(draft);inlineCategories[concept][activeId]=draft.category;}
}
function toggleInline(id){
  if(expandedId===id){rememberInlineDraft();expandedId=null;reviewInline=false;render();document.querySelector(`[data-transaction="${id}"] .details-toggle`)?.focus({preventScroll:true});}
  else openReview(id);
}
function openReview(id){
  const t=state().transactions.find(t=>t.id===id);if(!t)return;
  rememberInlineDraft();
  activeId=id;draft=structuredClone(inlineDrafts[concept][id]||initialDraft(t));
  if(inlineCategories[concept][id]!==undefined)draft.category=inlineCategories[concept][id];
  reviewInline=page==='inbox';
  if(reviewInline){closeSheet();expandedId=id;if(!visible().some(t=>t.id===id))filter='all';render();document.querySelector(`[data-transaction="${id}"]`)?.scrollIntoView({behavior:'smooth',block:'start'});}
  else renderReview();
}
function confirmInlineCategory(id){
  rememberInlineDraft();
  const t=state().transactions.find(t=>t.id===id);
  if(!t || t.kind==='transfer' || t.split || t.receipt || t.planId || inlineDrafts[concept][id]?.split){openReview(id);return;}
  const edit={...initialDraft(t),...inlineDrafts[concept][id],category:inlineCategories[concept][id]??t.category??t.suggestion??'',split:false};
  try{confirmReview(state(),id,edit);delete inlineDrafts[concept][id];delete inlineCategories[concept][id];persist();render();notify(`${t.name} reviewed in ${edit.category}.`);focusAfterReview(id);}
  catch(error){const el=document.querySelector(`[data-transaction="${id}"] .inline-error`);el.hidden=false;el.textContent=error.message;}
}
function focusAfterReview(id){
  const el=document.querySelector(`[data-transaction="${id}"] .focused-summary`)||document.querySelector('.focused-summary')||document.querySelector('.empty button');
  el?.focus({preventScroll:true});
}
function renderReview(){const t=state().transactions.find(t=>t.id===activeId);const plan=t.planId&&state().plans.find(p=>p.id===t.planId);
const receipt=`<div class="receipt"><div class="receipt-title">${t.receipt?'TARGET · SAMPLE RECEIPT':'SPLIT THIS PURCHASE'}</div>${draft.lines.map((l,i)=>`<div class="receipt-line" data-line-index="${i}"><div class="receipt-item-heading"><span>Item ${i+1}</span><button type="button" class="remove-line" data-action="remove-line" data-key="${i}" aria-label="Remove split item ${i+1}" ${draft.lines.length===1?'disabled':''}>${icon('close')}</button></div><div class="field-row"><label class="field">Item<input data-line="name" value="${esc(l.name)}" required maxlength="70"></label><label class="field">Amount ($)<input data-line="amount" type="number" value="${(l.amount/100).toFixed(2)}" min="0.01" step="0.01" inputmode="decimal" required></label></div><label class="field">Budget<select data-line="category">${options(l.category)}</select></label><label class="iou-switch"><input data-line="iou" type="checkbox" ${l.person||l.iouEnabled?'checked':''}>Someone owes me for this item</label><label class="field" data-person-field ${l.person||l.iouEnabled?'':'hidden'}>Who owes you?<input data-line="person" value="${esc(l.person)}" placeholder="e.g. Jamie" maxlength="40" ${l.person||l.iouEnabled?'required':''}></label></div>`).join('')}<button class="text-button" type="button" data-action="add-line">${icon('plus')} Add a split line</button><div class="receipt-total"><span>Split total</span><span id="split-total"></span></div><div class="receipt-difference" id="split-difference"></div></div>`;
const purpose=t.kind==='transfer'?`<div class="info-callout"><strong>This transfer is ${t.status} at the bank.</strong> Its purpose is ${t.reviewed?'confirmed':'still unclassified'}. ${t.reviewed?'You can change your decision below.':'Until you decide, it is excluded from income and spending.'}</div><div class="field">What was this transfer for?</div><div class="choice-list">${[['own','Between my own accounts','Moves money; doesn’t create income or spending.'],...(t.direction==='in'?[['income','Income received','Count this as income for this sample week.']]:[['expense','A purchase or expense','Choose a budget for the amount.']])].map(([v,label,sub])=>`<label class="choice"><input type="radio" name="classification" value="${v}" required ${draft.classification===v?'checked':''}><span>${label}<small>${sub}</small></span></label>`).join('')}</div><div id="transfer-category" ${draft.classification==='expense'?'':'hidden'}><label class="field">Budget category<select name="category">${options(draft.category,true)}</select></label></div>`:`<div class="mini-tabs" aria-label="Purchase allocation"><button type="button" data-action="allocation" data-key="whole" class="${draft.split?'':'active'}">One category</button><button type="button" data-action="allocation" data-key="split" class="${draft.split?'active':''}">Split & IOU</button></div>${draft.split?receipt:`<label class="field">Budget category<select name="category" required>${options(draft.category,true)}</select><small>${t.reviewed?'Your confirmed category.':'Suggestion only — your confirmation applies it.'}</small></label>`}`;
const title=t.kind==='transfer'?'Give this transfer a purpose':t.receipt?'A closer look at the receipt':'A little more context';
const content=`<div class="review-hero">${clay(t.icon,t.tone)}<div><h3>${esc(t.name)}</h3><div class="amount">${t.direction==='in'?'+':''}${money(t.amount)}</div><p>${dateText(t.date)} · ${esc(t.account)}</p></div></div><div class="status-row"><span class="badge ${t.status}">${t.status==='cash'?'User-confirmed cash':`Bank: ${t.status}`}</span><span class="badge ${t.reviewed?'reviewed':'match'}">${t.reviewed?'✓ Reviewed':t.changed?'Amount changed · review again':'Needs your review'}</span>${t.receipt?'<span class="badge">Receipt attached · sample</span>':''}</div><form id="review-form" data-transaction="${t.id}"><div class="form-stack">${purpose}${plan?`<div><div class="info-callout"><strong>Possible match: Winter coat</strong><br>Planned at UNIQLO for ${money(plan.low)}–${money(plan.high)} around ${dateText(plan.date)}. This is a clue, not a confirmed match.</div><label class="check-label"><input type="checkbox" name="matchPlan" ${draft.matchPlan?'checked':''}><span>Yes, this is my planned winter coat<small>Link this charge and release the ${money(plan.reserve)} reservation. The charge is counted once.</small></span></label></div>`:''}<label class="field">${t.kind==='transfer'?'What was it for? (optional)':'What did you buy? (optional)'}<input name="description" value="${esc(draft.description)}" placeholder="${t.id==='kahan'?'e.g. Toothbrush':'Add a useful description'}" maxlength="100"></label><details><summary class="details-summary">Note & priority</summary><div class="form-stack"><label class="field">A note for later<textarea name="note" placeholder="Anything you want to remember…" maxlength="500">${esc(draft.note)}</textarea></label><label class="field">How essential was it?<input name="priority" type="range" min="1" max="5" value="${draft.priority}" aria-label="Purchase priority"><span class="range-labels"><span>Nice to have</span><span>Essential</span></span></label></div></details></div><div class="sheet-actions"><p class="form-error" id="review-error" role="alert"></p><button class="primary" type="submit">${icon('check')} ${t.reviewed?'Save changes':'Confirm & review'}</button></div></form>${t.status==='pending'?`<div class="simulation"><p>TRY A BANK STATUS CHANGE · MOCK DATA ONLY</p><button class="secondary" data-action="post" data-id="${t.id}">Simulate this charge posting</button></div>`:''}`;
if(reviewInline){document.getElementById('details-'+activeId).innerHTML=`<p class="inline-account">${dateText(t.date)} · ${esc(t.account)}</p>${content}`;}else showSheet(title,content);
if(draft.split&&t.kind!=='transfer')updateSplitTotal();
$('#review-form').addEventListener('submit',e=>{e.preventDefault();readDraft();if(draft.split&&draft.lines.some(l=>l.iouEnabled&&!l.person)){return $('#review-error').textContent='Add the person’s name for each IOU item.';}try{confirmReview(state(),activeId,draft);persist();const id=activeId;delete inlineDrafts[concept][id];delete inlineCategories[concept][id];expandedId=null;reviewInline=false;closeSheet();render();notify('Reviewed. Your week is a little clearer.');focusAfterReview(id);}catch(err){$('#review-error').textContent=err.message;}});
}
function updateSplitTotal(){if(!$('#split-total'))return;const t=state().transactions.find(t=>t.id===activeId);const total=[...$('#review-form').querySelectorAll('[data-line="amount"]')].reduce((n,el)=>n+Math.round(Number(el.value)*100),0);$('#split-total').textContent=money(total);const diff=t.amount-total;$('#split-difference').textContent=diff?`${money(Math.abs(diff))} ${diff>0?'left to allocate':'over the receipt total'}`:`Matches ${money(t.amount)} receipt total`;$('#split-difference').className='receipt-difference'+(!diff?' ok':'');}
function about(){showSheet('A space to try things',`<p class="body-copy">This is a temporary SaveUp inbox prototype, made for reviewing your week on your phone. All names, amounts, accounts, and receipts are fictional.</p><div class="info-callout">No bank is connected. No Plaid credentials, receipt uploads, money movement, or messages to friends are involved. Your edits are saved only in this browser.</div><div class="about-actions"><button class="secondary" data-action="share">${icon('share')} Copy inbox link</button><button class="secondary" data-action="feedback">${icon('edit')} Save a feedback note</button><button class="secondary" data-action="reset">${icon('reset')} Reset Focused Inbox</button></div><p class="body-copy">On iPhone: open the preview link in Safari and sign in with the same ChatGPT account if asked. Optional: Share → Add to Home Screen.</p>`);}
function reset(){showSheet('Start your inbox fresh?',`<p class="body-copy">Restore the eight sample transactions in Focused Inbox. Your inbox changes and feedback will be cleared.</p><div class="button-pair"><button class="secondary" data-action="close">Keep my changes</button><button class="primary" data-action="confirm-reset">Reset demo</button></div>`);}
function dates(){rememberInlineDraft();showSheet('Choose your inbox window',`<p class="body-copy">The sample week begins on Sunday, October 25. Choose a different range to narrow what you’re reviewing.</p><form id="date-form" class="form-stack"><div class="field-row"><label class="field">From<input type="date" name="start" value="${state().range.start}" required></label><label class="field">Through<input type="date" name="end" value="${state().range.end}" required></label></div><p class="form-error" id="date-error" role="alert"></p><button class="primary">Show this range</button><button type="button" class="secondary" data-action="sample-week">Restore sample week</button></form>`);$('#date-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),start=f.get('start'),end=f.get('end');if(start>end)return $('#date-error').textContent='The end date needs to come after the start date.';state().range={start,end};expandedId=null;reviewInline=false;persist();closeSheet();render();});}
function manual(){showSheet('Record a cash purchase',`<p class="body-copy">Try adding a sample cash purchase. Cash is user-confirmed; it does not wait for a bank match.</p><form id="manual-form" class="form-stack"><label class="field">Store or purchase<input name="name" placeholder="e.g. Farmers market" maxlength="60" required></label><div class="field-row"><label class="field">Amount ($)<input name="amount" type="number" min="0.01" max="100000" step="0.01" inputmode="decimal" required></label><label class="field">Date<input name="date" type="date" value="2026-10-31" required></label></div><label class="field">Suggested category<select name="category">${options('Essentials')}</select></label><button class="primary">${icon('plus')} Add to inbox for review</button></form>`);$('#manual-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),date=f.get('date');state().transactions.unshift({id:'cash-'+crypto.randomUUID(),name:f.get('name').trim(),amount:Math.round(Number(f.get('amount'))*100),date,kind:'purchase',status:'cash',account:'Cash · manual entry',icon:'wallet',tone:'peach',suggestion:f.get('category'),hint:'Manual cash · needs review',reviewed:false});if(date<state().range.start)state().range.start=date;if(date>state().range.end)state().range.end=date;page='inbox';filter='needs';persist();closeSheet();render();notify('Cash purchase added. Tap it to review.');});}
function scan(){showSheet('Try a sample receipt',`<div class="review-hero">${clay('receipt','pink')}<div><h3>Target</h3><div class="amount">$26.48</div><p>3 items · matches the sample card charge</p></div></div><div class="receipt"><div class="receipt-title">TARGET · DEMO ONLY</div><div class="receipt-total"><span>Shampoo</span><span>$12.99</span></div><div class="receipt-total"><span>Chocolate bar</span><span>$4.49</span></div><div class="receipt-total"><span>Kitchen towels</span><span>$9.00</span></div><hr style="border:0;border-top:1px dashed #ddd;margin:18px 0"><div class="receipt-total"><span>TOTAL</span><span>$26.48</span></div></div><p class="body-copy">Receipt scanning is simulated in this prototype. Open the sample to edit item names, split categories, or assign the chocolate bar to a friend. It uses the existing Target charge, so no duplicate purchase is added.</p><button class="primary" data-action="review" data-id="target">Use this sample receipt ${icon('chevron')}</button>`);}
function post(id){rememberInlineDraft();const t=state().transactions.find(t=>t.id===id);showSheet('Try pending → posted',`<p class="body-copy">Simulate the bank finalizing ${esc(t.name)}. The posted charge replaces the pending amount. A changed amount asks you to review it again.</p><form id="post-form" class="form-stack"><label class="field">Final posted amount ($)<input name="amount" type="number" min="0.01" max="100000" step="0.01" value="${(t.amount/100).toFixed(2)}" inputmode="decimal" required></label><button class="primary">Simulate posted charge</button></form>`);$('#post-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const changed=postPending(state(),id,Math.round(Number(f.get('amount'))*100));delete inlineDrafts[concept][id];delete inlineCategories[concept][id];expandedId=null;reviewInline=false;persist();closeSheet();render();notify(changed?'Amount changed. This purchase needs review again.':'Posted — the pending amount was replaced.');});}
function feedback(){const f=state().feedback;showSheet('What feels right?',`<p class="body-copy">Keep a local note about <strong>Focused Inbox</strong>. Copy it into our chat when you’re ready. It isn’t sent anywhere automatically.</p><form id="feedback-form" class="form-stack"><label class="field">How does this inbox feel?<select name="rating"><option value="">Choose a reaction</option>${['My favorite','Promising, with changes','Not for me'].map(x=>`<option ${x===f.rating?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">What would you change?<textarea name="note" rows="4" maxlength="2000" placeholder="The part I like… The part that gets in my way…">${esc(f.note)}</textarea></label><button class="primary">Save note in this browser</button><button type="button" class="secondary" data-action="copy-feedback">Copy feedback note</button></form>`);$('#feedback-form').addEventListener('submit',e=>{e.preventDefault();saveFeedback();closeSheet();notify('Feedback saved in this browser.');});}
function saveFeedback(){if($('#feedback-form')){const f=new FormData($('#feedback-form'));state().feedback={rating:f.get('rating'),note:f.get('note')};persist();}}
async function copyText(text){try{await navigator.clipboard.writeText(text);notify('Copied. Ready to paste.');}catch{showSheet('Copy this text',`<label class="field">Press and hold to copy<textarea rows="7" readonly>${esc(text)}</textarea></label>`);}}
document.addEventListener('input',e=>{if(e.target.matches('[data-line="amount"]'))updateSplitTotal();});
document.addEventListener('change',e=>{if(e.target.matches('.inline-category')){inlineCategories[concept][e.target.dataset.id]=e.target.value;return;}if(e.target.name==='classification')$('#transfer-category').hidden=e.target.value!=='expense';if(e.target.matches('[data-line="iou"]')){const field=e.target.closest('.receipt-line').querySelector('[data-person-field]');field.hidden=!e.target.checked;field.querySelector('input').required=e.target.checked;}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,key,id}=b.dataset;
switch(action){
 case 'page':rememberInlineDraft();expandedId=null;reviewInline=false;page=key;render();window.scrollTo({top:0,behavior:'instant'});break;
 case 'filter':rememberInlineDraft();expandedId=null;reviewInline=false;filter=key;render();break;
 case 'review':openReview(id);break;
 case 'inline-details':toggleInline(id);break;
 case 'inline-confirm':confirmInlineCategory(id);break;
 case 'close':closeSheet();break;
 case 'about':about();break;
 case 'dates':dates();break;
 case 'sample-week':rememberInlineDraft();expandedId=null;reviewInline=false;state().range={start:'2026-10-25',end:'2026-10-31'};persist();closeSheet();render();break;
 case 'manual':manual();break;
 case 'scan':scan();break;
 case 'post':post(id);break;
 case 'allocation':readDraft();draft.split=key==='split';renderReview();break;
 case 'add-line':readDraft();draft.lines.push({name:'',amount:0,category:'Essentials',person:''});renderReview();break;
 case 'remove-line':readDraft();if(draft.lines.length>1){draft.lines.splice(Number(key),1);renderReview();}break;
 case 'reset':reset();break;
 case 'confirm-reset':expandedId=null;reviewInline=false;inlineDrafts[concept]={};inlineCategories[concept]={};states[concept]=fresh();persist();filter='needs';page='inbox';closeSheet();render();notify('A fresh week, ready to try.');break;
 case 'share':{const u=new URL(location.href);u.searchParams.delete('concept');copyText(u.href);break;}
 case 'feedback':feedback();break;
 case 'copy-feedback':saveFeedback();copyText(`Focused Inbox: ${state().feedback.rating||'No reaction yet'}\n${state().feedback.note||'No note yet'}`);break;
}});
render();
